class Solution {
    public: int numSubseq(vector<int>& nums,int target){
        sort(nums.begin(),nums.end());
        const long long mod=1000000007;
        vector<long long> powers(nums.size(),1);
        for(int i=1;i<(int)nums.size();++i)powers[i]=powers[i-1]*2%mod;
        int left=0,right=nums.size()-1;
        long long answer=0;
        while(left<=right)if(nums[left]+nums[right]<=target){
            answer=(answer+powers[right-left])%mod;
            ++left;
        }else --right;
        return answer;
    }
};
